INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K001', 'なぜ人は呼吸するのか', 'physiology', '["基礎","酸素","二酸化炭素"]', '["なぜ呼吸するの？","息をする目的は？"]', '呼吸は、体に必要な酸素を取り込み、体で生じた二酸化炭素を外に出す働きです。', '肺から血液、細胞へとつながる流れを学びます。酸素は、細胞が栄養からATPをつくる過程で使われます。酸素そのものがATPに変わるという意味ではありません。', '["P01","P03","P160"]', '["酸素そのものがATPに変わるとは説明しない。"]', '["EXT01","EXT03"]', '[]', 'editorial_draft', 'educational_explanation', true, false, false, '["I001","I002"]', '[1,4]', '["I001","I002"]', '[{"issue_id":"I001","rule":"酸素は、細胞が栄養からATPをつくる過程で使われます。"},{"issue_id":"I002","rule":"「内呼吸」と「細胞呼吸」の用語欄を分け、それぞれの定義を監修後に掲載する。"}]', '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K002', '呼吸の流れを4つに分けて理解する', 'physiology', '["全体像","換気","ガス交換","ATP"]', '["呼吸は肺だけの働き？"]', 'この教材では、空気の出入り、肺胞でのガス交換、血液による運搬、細胞でのエネルギー産生という流れで学びます。', '肺だけで完結するのではなく、血液循環や細胞の働きまでつなげて理解するための整理です。', '["P02"]', '["原図の「内呼吸＝Cellular Respiration」は用語確認待ち。回答では「細胞呼吸」と表現し、内呼吸と同義だと断定しない。"]', '[]', '[]', 'editorial_draft', 'educational_explanation', true, false, false, '["I002"]', '[1]', '["I002"]', '[{"issue_id":"I002","rule":"「内呼吸」と「細胞呼吸」の用語欄を分け、それぞれの定義を監修後に掲載する。"}]', '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K003', '換気とは', 'physiology', '["肺","横隔膜","吸気","呼気"]', '["換気って何？","肺は自分で動くの？","肺は筋肉なの？","呼吸筋という筋肉が肺にあるの？"]', '換気は、空気を肺に出し入れすることです。', '肺は、自分で筋肉を縮めて空気を吸い込む器官ではありません。横隔膜や肋骨の間の筋肉が働いて胸の中の空間を広げると、それに伴って肺が膨らみ、空気が入ります。', '["P02","P03","P037","P151","P152","P154","P155"]', '["著者指定：肺自身が筋肉として収縮し吸気を起こすわけではないことを説明する。「呼吸筋」は肺にある固有の筋肉名として使わない。"]', '["EXT01"]', '["C007","C012","C013","C014"]', 'editorial_draft', 'educational_explanation', true, false, false, '["I002","I017","I031","I032","I034"]', '[1,2,3]', '["I002","I017","I031","I032","I034"]', '[{"issue_id":"I002","rule":"「内呼吸」と「細胞呼吸」の用語欄を分け、それぞれの定義を監修後に掲載する。"},{"issue_id":"I017","rule":"ファイル上の章番号と図中の章番号を別に保存し、正式な章割りが決まった後に見出しを統一する。"},{"issue_id":"I031","rule":"一呼吸の周期と肺まで空気が移動する時間を区別する。「約0.5秒」「0.9秒」は定義・根拠確認まで掲載しない。"},{"issue_id":"I032","rule":"肺は、自分で筋肉を縮めて空気を吸い込む器官ではありません。横隔膜や肋骨の間の筋肉が働いて胸の中の空間を広げると、それに伴って肺が膨らみ、空気が入ります。"},{"issue_id":"I034","rule":"図に圧の測定部位・基準・単位・呼吸条件を明記する。確認前は「呼気時の胸腔内圧は陽圧」という一律の説明を外す。"}]', '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K004', '肺胞で起こるガス交換', 'physiology', '["肺胞","外呼吸","毛細血管"]', '["肺胞は何をしているの？"]', '肺胞では、酸素が血液へ入り、二酸化炭素が血液から肺胞へ移ります。', '原稿が「外呼吸」と呼ぶ部分です。肺に空気を出し入れする換気と、その空気と血液の間でガスを交換する働きを区別して学びます。', '["P02","P03","P034","P156","P161"]', '[]', '["EXT01"]', '[]', 'editorial_draft', 'educational_explanation', true, false, false, '["I002","I037"]', '[1,2,3,4]', '["I002","I037"]', '[{"issue_id":"I002","rule":"「内呼吸」と「細胞呼吸」の用語欄を分け、それぞれの定義を監修後に掲載する。"},{"issue_id":"I037","rule":"肺胞数は出典と条件が確認できた数値のみを記載する。確認前は「多数の肺胞」という説明にとどめる。"}]', '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K005', '酸素はどうやって全身に届くのか', 'physiology', '["赤血球","ヘモグロビン","心臓"]', '["酸素は血液で運ばれる？"]', '取り込んだ酸素は主に赤血球のヘモグロビンと結び付き、血液の流れで全身へ運ばれます。', '心臓はその血液を送り出すポンプとして働きます。呼吸と循環を一緒に理解するための項目です。', '["P03","P039","P162","P163","P164"]', '["血管長や全細胞数を根拠未確認のまま付け足さない。"]', '["EXT01"]', '[]', 'editorial_draft', 'educational_explanation', true, false, false, '["I002","I036","I037"]', '[1,4]', '["I002","I036","I037"]', '[{"issue_id":"I002","rule":"「内呼吸」と「細胞呼吸」の用語欄を分け、それぞれの定義を監修後に掲載する。"},{"issue_id":"I036","rule":"酸素タクシーは、結合部位を学ぶためのたとえです。必ず満席で出発し、全部を降ろすという意味ではありません。"},{"issue_id":"I037","rule":"肺胞数は出典と条件が確認できた数値のみを記載する。確認前は「多数の肺胞」という説明にとどめる。"}]', '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K006', 'ATPとは', 'cell_energy', '["ATP","エネルギー","酸素"]', '["ATPって何？","酸素がATPになるの？"]', 'ATPは、細胞が活動に必要なエネルギーをやり取りするために使う分子です。', '酸素がそのままATPに変わるわけではありません。酸素は、栄養から得たエネルギーを使ってATPを作る過程を支えます。原稿の「エネルギー通貨」は、この役割を伝えるたとえです。', '["P01","P04","P043","P165","P168"]', '["「酸素がエネルギーに変わる」という原文は修正提案として別保存。"]', '["EXT03"]', '[]', 'editorial_draft', 'educational_explanation', true, false, false, '["I001","I020","I038"]', '[1,4,5]', '["I001","I020","I038"]', '[{"issue_id":"I001","rule":"酸素は、細胞が栄養からATPをつくる過程で使われます。"},{"issue_id":"I020","rule":"ATPの再利用の説明を残し、「1日に体重の約100倍」の数値は根拠確認まで掲載しない。"},{"issue_id":"I038","rule":"細胞数とミトコンドリア数は分けて記載する。計算例として37兆×1.5µmを使うなら55,500km。ただし実際の総数・長さの説明としては未確定。"}]', '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K007', 'ミトコンドリアの役割', 'cell_energy', '["細胞","ミトコンドリア","ATP"]', '["ミトコンドリアと呼吸はどう関係する？"]', 'ミトコンドリアは、多くの細胞でATPの産生を担う細胞内の構造です。', '原稿では「細胞の発電所」とたとえています。吸い込んだ酸素と細胞内の働きを結び付けて学ぶための説明です。', '["P07","P044","P167","P168","P170"]', '["すべての細胞にミトコンドリアがあるとは書かない。ATP産生量の数値と細胞数の換算は保留。"]', '["EXT03"]', '[]', 'editorial_draft', 'educational_explanation', true, false, false, '["I003","I004","I005","I021","I038"]', '[1,5]', '["I003","I004","I005","I021","I038"]', '[{"issue_id":"I003","rule":"ATPの産生・利用は繰り返されています。原稿の「1分間に約2〜3kg」は根拠確認まで掲載しない。"},{"issue_id":"I004","rule":"多くの細胞では、ミトコンドリアがATPの産生に関わります。"},{"issue_id":"I005","rule":"37兆個（370,000億個）。※単位換算のみの修正案。37兆個という生物学的な数値の妥当性とは別。"},{"issue_id":"I021","rule":"糖からエネルギーを取り出す過程は複数あります。反応の場所と酸素の必要性を分けた図に描き直し、監修を受ける。"},{"issue_id":"I038","rule":"細胞数とミトコンドリア数は分けて記載する。計算例として37兆×1.5µmを使うなら55,500km。ただし実際の総数・長さの説明としては未確定。"}]', '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K008', '二酸化炭素と呼吸調節', 'co2', '["CO₂","呼吸中枢"]', '["二酸化炭素は不要なもの？"]', '二酸化炭素は体外へ排出される一方、呼吸の調節にも関係しています。', '脳などが血液中の二酸化炭素や酸素に関する情報を受け取り、必要に応じて呼吸を調整します。二酸化炭素だけを唯一の呼吸スイッチと考えないことが大切です。', '["P05","P06","P049","P183"]', '["CO₂を意図的に増やす練習や息止めへ誘導しない。"]', '["EXT02"]', '["C006","C011"]', 'editorial_draft', 'educational_explanation', true, false, false, '["I007","I043"]', '[1,6,7]', '["I007","I043"]', '[{"issue_id":"I007","rule":"CO₂は呼吸調節に関わります。「CO₂だけが呼吸を決める」「CO₂耐性がヨガの効果を確定する」という説明は削除候補にする。"},{"issue_id":"I043","rule":"引用欄に著者・資料名・発行年・個別URL・参照箇所を記載する。機関名だけの引用は根拠の確定に使わない。"}]', '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K009', '二酸化炭素と血液のpH', 'co2', '["pH","酸塩基"]', '["二酸化炭素とpHは関係する？"]', '教材では、二酸化炭素の変化が血液の酸性・アルカリ性のバランスに関わると説明しています。', 'この項目は教材の生理学的説明です。自分の呼吸の感覚だけから血液のpHを推定したり、呼吸法でpHを調整しようとする指示には使いません。', '["P05"]', '["臨床的な酸塩基評価・治療への転用不可。外部検証は未実施。"]', '[]', '[]', 'editorial_draft', 'educational_explanation', true, false, false, '["I007"]', '[1]', '["I007"]', '[{"issue_id":"I007","rule":"CO₂は呼吸調節に関わります。「CO₂だけが呼吸を決める」「CO₂耐性がヨガの効果を確定する」という説明は削除候補にする。"}]', '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K010', 'ボーア効果とは', 'co2', '["ボーア効果","ヘモグロビン","酸素"]', '["ボーア効果をやさしく説明して"]', '教材では、二酸化炭素が増えpHが低下する組織側で、ヘモグロビンが酸素を放しやすくなることをボーア効果として紹介しています。', '働いている組織への酸素の受け渡しを理解する項目です。「CO₂は多いほどよい」という意味には使いません。', '["P05"]', '["効果を理由に息止め・過剰なCO₂保持を勧めない。外部検証は未実施。"]', '[]', '[]', 'editorial_draft', 'educational_explanation', true, false, false, '["I007"]', '[1]', '["I007"]', '[{"issue_id":"I007","rule":"CO₂は呼吸調節に関わります。「CO₂だけが呼吸を決める」「CO₂耐性がヨガの効果を確定する」という説明は削除候補にする。"}]', '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K011', '呼吸数を観察する', 'observation', '["セルフチェック","1分","記録"]', '["自分の呼吸を知るには？","呼吸数をどう数える？"]', '原稿では、安静にして、いつも通りの呼吸を1分間数える観察を紹介しています。', '回数と一緒に、そのときの体調や状況も記録しましょう。数値だけで良し悪しを判断せず、観察のための記録として扱います。', '["P08"]', '["原図の「8回以下はとても良い」を使用しない。呼吸数だけで健康状態や疾患を判定しない。"]', '[]', '["C001"]', 'editorial_draft', 'educational_explanation', true, false, false, '["I006"]', '[1]', '["I006"]', '[{"issue_id":"I006","rule":"安静時の呼吸数を記録し、そのときの状態と一緒に振り返りましょう。回数だけで「良い・悪い」を採点しません。"}]', '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K012', '胸やお腹の動きを観察する', 'observation', '["胸郭","腹部","肩","鼻呼吸"]', '["呼吸のどこを観察する？"]', '息の通り道、胸やお腹の動き、肩や首の力みなどを観察します。', '教材のチェック項目を、体の動きに気づくための観察として整理しました。「お腹が動かないから横隔膜が使えていない」などの診断には用いません。', '["P09","P157"]', '["原図の呼吸タイプ名は教材独自の分類として扱い、医学的診断名にしない。"]', '[]', '[]', 'editorial_draft', 'educational_explanation', true, false, false, '["I006"]', '[1,3]', '["I006"]', '[{"issue_id":"I006","rule":"安静時の呼吸数を記録し、そのときの状態と一緒に振り返りましょう。回数だけで「良い・悪い」を採点しません。"}]', '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K013', '呼吸カルテに記録すること', 'observation', '["カルテ","朝昼夜","気分"]', '["呼吸記録には何を書けばいい？"]', '呼吸数、鼻や口の呼吸、呼吸の感覚と、その日の睡眠・疲労感・気分などを記録します。', '第1章の呼吸カルテと第5部のワークを別の様式として保存しています。記録は変化に気づく材料であり、記録だけで病気や原因を決めるものではありません。', '["P10","P27","P176","P190","P201","P205","P222"]', '["宣伝文の「AIが最適な改善提案」を実装済み機能として案内しない。"]', '[]', '["C001","C002","C003","C004","C005","C006","C007","C008","C009","C010"]', 'editorial_draft', 'educational_explanation', true, false, false, '["I013"]', '[1,6,7,8,12,17]', '["I013"]', '[{"issue_id":"I013","rule":"この教材では、睡眠・集中などに関連する学習テーマとして呼吸を紹介します。個人の改善を保証する表現は削る。"}]', '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K014', 'プラーナとは', 'yoga_theory', '["伝統的概念","プラーナ"]', '["プラーナは酸素のこと？"]', 'プラーナは、ヨガで生命エネルギーを表すために使われる伝統的な考え方です。', '教材では呼吸を通して心と体を整える文脈で扱っています。酸素やATPと同じ物質・測定値としては登録していません。', '["P15"]', '["プラーナ＝酸素、ATP、神経活動という同一視をしない。"]', '[]', '["C001","C002","C003","C004","C005","C006","C007","C008","C009","C010"]', 'editorial_draft', 'traditional_explanation', true, false, false, '["I008","I009"]', '[17]', '["I008","I009"]', '[{"issue_id":"I008","rule":"引用するCYPの版・発行年・ページを明記する。シータリーの掲載を確認できるまでは「このCYPに明記」と書かない。"},{"issue_id":"I009","rule":"簡易版の本文に合わせ、耳を塞ぐ動作は手順に追加しない。イラストも本文と一致させる。"}]', '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K015', 'プラーナーヤーマとは', 'yoga_theory', '["呼吸への気づき","ヨガ"]', '["プラーナーヤーマとは？","ヨガの呼吸法は息止め？"]', 'この教材では、呼吸に気づき、呼吸を意識的に整えるヨガの実践として説明しています。', '長く息を止めたり、強く呼吸したりすることだけを指すのではありません。観察と無理のない実践を大切にしています。', '["P12","P15"]', '[]', '[]', '["C001","C002","C003","C004","C005","C006","C007","C008","C009","C010"]', 'editorial_draft', 'traditional_explanation', true, false, false, '["I008","I009"]', '[17]', '["I008","I009"]', '[{"issue_id":"I008","rule":"引用するCYPの版・発行年・ページを明記する。シータリーの掲載を確認できるまでは「このCYPに明記」と書かない。"},{"issue_id":"I009","rule":"簡易版の本文に合わせ、耳を塞ぐ動作は手順に追加しない。イラストも本文と一致させる。"}]', '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K016', '初心者の息止めの扱い', 'safety', '["初心者","保息","息止め"]', '["初心者も息を止める必要がある？"]', 'この教材の初心者向け実践は、息止めを入れない形を基本にしています。', 'ナディショーダナ簡易版では保息を入れません。ボックス呼吸や4-7-8呼吸の説明を、そのまま初心者用の実践指示にしないよう区別しています。', '["P16","P23","P26"]', '[]', '[]', '["C001","C002","C006","C007","C005","C008"]', 'editorial_draft', 'educational_explanation', true, false, false, '["I008","I009","I010","I011","I012","I013"]', '[17]', '["I008","I009","I010","I011","I012","I013"]', '[{"issue_id":"I008","rule":"引用するCYPの版・発行年・ページを明記する。シータリーの掲載を確認できるまでは「このCYPに明記」と書かない。"},{"issue_id":"I009","rule":"簡易版の本文に合わせ、耳を塞ぐ動作は手順に追加しない。イラストも本文と一致させる。"},{"issue_id":"I010","rule":"この教材では、初心者はカパラバティの特徴と注意点を学びます。実践の回数は案内しません。"},{"issue_id":"I011","rule":"該当する注意は「本教材の方針」として記載し、CYPのカパラバティ節にあると断定しない。"},{"issue_id":"I012","rule":"保息の長さや有無を変える場合は、別の変種として名称・手順・出典を記載する。確定前の手順は案内しない。"},{"issue_id":"I013","rule":"この教材では、睡眠・集中などに関連する学習テーマとして呼吸を紹介します。個人の改善を保証する表現は削る。"}]', '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K017', 'ヨガ呼吸法と現代呼吸法を区別する', 'yoga_theory', '["由来","比較","ボックス呼吸","4-7-8"]', '["ボックス呼吸は伝統的なヨガ？"]', 'この教材では、ヨガの体系に位置付ける呼吸法と、ボックス呼吸などの現代呼吸法を分けて整理しています。', '優劣を決める分類ではありません。由来、実践の目的、教材での扱いを区別するための分類です。', '["P24","P26"]', '["教材内分類を、すべての流派や歴史に共通する断定に拡張しない。"]', '[]', '["C001","C002","C003","C004","C005","C006","C007","C008","C009","C010"]', 'editorial_draft', 'traditional_explanation', true, false, false, '["I008","I013","I012"]', '[17]', '["I008","I013","I012"]', '[{"issue_id":"I008","rule":"引用するCYPの版・発行年・ページを明記する。シータリーの掲載を確認できるまでは「このCYPに明記」と書かない。"},{"issue_id":"I013","rule":"この教材では、睡眠・集中などに関連する学習テーマとして呼吸を紹介します。個人の改善を保証する表現は削る。"},{"issue_id":"I012","rule":"保息の長さや有無を変える場合は、別の変種として名称・手順・出典を記載する。確定前の手順は案内しない。"}]', '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K018', '実践を中止する目安と共通の注意', 'safety', '["中止","めまい","苦しさ"]', '["呼吸法でめまいが出たら？"]', '教材の共通ルールは、苦しくなるまで続けないこと、めまいが出たら中止することです。', '不調を押して練習を続けません。慢性疾患・痛み・心臓の問題がある場合や妊娠中などは、教材の相談方針を確認してください。症状の診断や個別の実施可否を、このDBだけで判断しません。', '["P23","P29","P055"]', '["全呼吸法に完全な禁忌リストが揃っているとは扱わない。"]', '[]', '["C001","C002","C003","C004","C005"]', 'editorial_draft', 'educational_explanation', true, false, false, '["I010","I011"]', '[8,17]', '["I010","I011"]', '[{"issue_id":"I010","rule":"この教材では、初心者はカパラバティの特徴と注意点を学びます。実践の回数は案内しません。"},{"issue_id":"I011","rule":"該当する注意は「本教材の方針」として記載し、CYPのカパラバティ節にあると断定しない。"}]', '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K019', '教材のCYP参照範囲', 'yoga_theory', '["CYP","出典","版"]', '["この教材のCYPの出典は？"]', '教材には、インド政府サイトのCommon Yoga Protocolへのリンクがあります。', '引用先の版と教材の内容には照合が必要な箇所があります。特にシータリーの掲載説明は保留し、CYPに掲載されていると断定する回答には使いません。', '["P19","P24","P229"]', '["CYP掲載と科学的効果の検証済みを同一視しない。"]', '["EXT04"]', '["C001","C002","C003","C004","C005","C008","C009","C010"]', 'editorial_draft', 'traditional_explanation', true, false, false, '["I008","I013","I009","I012"]', '[15,17]', '["I008","I013","I009","I012"]', '[{"issue_id":"I008","rule":"引用するCYPの版・発行年・ページを明記する。シータリーの掲載を確認できるまでは「このCYPに明記」と書かない。"},{"issue_id":"I013","rule":"この教材では、睡眠・集中などに関連する学習テーマとして呼吸を紹介します。個人の改善を保証する表現は削る。"},{"issue_id":"I009","rule":"簡易版の本文に合わせ、耳を塞ぐ動作は手順に追加しない。イラストも本文と一致させる。"},{"issue_id":"I012","rule":"保息の長さや有無を変える場合は、別の変種として名称・手順・出典を記載する。確定前の手順は案内しない。"}]', '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K020', '鼻の働き', 'physiology', '["鼻","鼻呼吸","加温","加湿"]', '["鼻の働きとは？"]', '教材では鼻の働きを、ろ過・加温・加湿・嗅覚の4つに分けています。', '空気の通り道を学ぶ項目です。鼻呼吸だけで病気を防げるという説明には広げません。', '["P030","P196","P208"]', '["原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。"]', '[]', '[]', 'editorial_draft', 'educational_explanation', true, false, false, '["I047"]', '[2,7,8]', '["I047"]', '[{"issue_id":"I047","rule":"鼻の構造・NOの説明と、脳・免疫・いびき・睡眠への効果の主張を別に扱う。効能の矢印は根拠確認まで保留する。"}]', '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K021', '副鼻腔とは', 'physiology', '["副鼻腔","NO","一酸化窒素"]', '["副鼻腔とはとは？"]', '副鼻腔は鼻のまわりの骨の中にある空洞です。', '教材には一酸化窒素（NO）との関係も記載されていますが、集中力・免疫・運動効果までの説明は別途検証が必要です。', '["P031"]', '["原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。"]', '[]', '[]', 'editorial_draft', 'educational_explanation', true, false, false, '["I015"]', '[2]', '["I015"]', '[{"issue_id":"I015","rule":"副鼻腔の構造の説明を残し、集中力・免疫・運動能力への効果は根拠確認まで別欄で保留する。"}]', '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K022', '咽頭と喉頭の役割', 'physiology', '["咽頭","喉頭","声帯"]', '["咽頭と喉頭の役割とは？"]', '教材では、咽頭を空気と食べ物の通り道、喉頭を声と気管の保護に関わる場所として説明しています。', '空気の流れと発声の学習をつなぐ項目です。', '["P032"]', '["原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。"]', '[]', '[]', 'editorial_draft', 'educational_explanation', true, false, false, '[]', '[2]', '[]', '[]', '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K023', '気管と気管支', 'physiology', '["気管","気管支","線毛"]', '["気管と気管支とは？"]', '気管から左右の肺へ分かれる気管支は、さらに枝分かれして肺の中へ空気を届けます。', '教材は粘液や線毛も紹介しています。構造の説明として扱います。', '["P033"]', '["原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。"]', '[]', '[]', 'editorial_draft', 'educational_explanation', true, false, false, '[]', '[2]', '[]', '[]', '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K024', '肺胞とサーファクタント', 'physiology', '["肺胞","サーファクタント"]', '["肺胞とサーファクタントとは？"]', '教材ではサーファクタントを、肺胞がつぶれにくくなるよう助けるものとして紹介しています。', '肺胞の構造と働きの学習用です。', '["P035"]', '["原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。"]', '[]', '[]', 'editorial_draft', 'educational_explanation', true, false, false, '[]', '[2]', '[]', '[]', '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K025', '胸郭とは', 'physiology', '["胸郭","肋骨","肋間筋"]', '["胸郭とはとは？"]', '胸郭は、肋骨・胸骨・背骨で構成される胸のかご状の構造です。', '胸郭の動きと呼吸を結び付けて学びます。安静時と力を入れて吐く場合の筋活動は区別します。', '["P036","P153"]', '["原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。"]', '[]', '[]', 'editorial_draft', 'educational_explanation', true, false, false, '["I016","I033"]', '[2,3]', '["I016","I033"]', '[{"issue_id":"I016","rule":"安静時に吐く場合と、力を入れて吐く場合を分けて説明する。筋肉名と図の動作は監修後に確定する。"},{"issue_id":"I033","rule":"肋骨の動きの名称・方向・胸骨との接続先を監修し、図と本文を同時に修正する。"}]', '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K026', '横隔膜とは', 'physiology', '["横隔膜","吸気","呼気"]', '["横隔膜とはとは？"]', '横隔膜は胸とお腹を隔てるドーム状の筋肉です。吸うときに収縮して下がり、胸の空間を広げます。', '横隔膜や肋骨の間の筋肉が胸の中の空間を動かすことで、肺が膨らみます。肺自身が筋肉として縮んで空気を吸い込むという意味ではありません。安静時に吐くときは横隔膜がゆるみます。', '["P037","P150"]', '["原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。"]', '[]', '["C012","C013","C014"]', 'editorial_draft', 'educational_explanation', true, false, false, '["I017"]', '[2,3]', '["I017"]', '[{"issue_id":"I017","rule":"ファイル上の章番号と図中の章番号を別に保存し、正式な章割りが決まった後に見出しを統一する。"}]', '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K027', '死腔と肺胞換気', 'physiology', '["死腔","肺胞換気","1回換気量"]', '["死腔と肺胞換気とは？"]', '吸った空気のすべてがガス交換に使われるわけではありません。教材はガス交換に直接参加しない空気の通り道を死腔として説明しています。', '1回の量と回数の両方が肺胞に届く空気量に関係します。原図の500mL・1000mLなどは比較例であり、深く吸う練習の目標値にはしません。', '["P038"]', '["原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。"]', '[]', '["C012","C013","C014"]', 'editorial_draft', 'educational_explanation', true, false, false, '["I017","I018"]', '[3]', '["I017","I018"]', '[{"issue_id":"I017","rule":"ファイル上の章番号と図中の章番号を別に保存し、正式な章割りが決まった後に見出しを統一する。"},{"issue_id":"I018","rule":"この図は、死腔と肺胞換気を理解するための計算例です。呼吸を大きくする練習の目標値ではありません。"}]', '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K028', '肺循環と体循環', 'physiology', '["心臓","肺循環","体循環"]', '["肺循環と体循環とは？"]', '肺循環は心臓と肺を結ぶ流れ、体循環は心臓と全身を結ぶ流れです。', '教材は心臓を酸素の運搬を支えるポンプとして説明しています。', '["P040","P160","P164"]', '["原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。"]', '[]', '[]', 'editorial_draft', 'educational_explanation', true, false, false, '["I037"]', '[4]', '["I037"]', '[{"issue_id":"I037","rule":"肺胞数は出典と条件が確認できた数値のみを記載する。確認前は「多数の肺胞」という説明にとどめる。"}]', '5.0') ON CONFLICT (knowledge_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_knowledge (knowledge_id, title, category_id, tags, example_questions, answer_short, answer_detail, source_passage_ids, editorial_notes, external_check_ids, related_catalog_ids, review_state, content_kind, preview_allowed, production_ready, clinical_efficacy_verified, issue_ids, chapter_numbers, editorial_correction_ids, answer_constraints, editorial_policy_version) VALUES ('K029', 'SpO₂の読み方', 'observation', '["SpO₂","酸素飽和度","パルスオキシメータ"]', '["SpO₂の読み方とは？"]', 'SpO₂は、血液中のヘモグロビンと酸素の結び付きの割合を推定する指標です。', '測定には誤差や限界があります。値だけで健康・不調を判定せず、症状や測定条件も含めて扱います。', '["P041","P158"]', '["原図の主要箇所を目視確認した要約。効能・個別適用の審査とは別。"]', '["EXT05"]', '[]', 'editorial_draft', 'educational_explanation', true, false, false, '["I019","I035"]', '[4]', '["I019","I035"]', '[{"issue_id":"I019","rule":"SpO₂の数値だけで健康状態を採点しません。測定条件や症状も含めて扱います。"},{"issue_id":"I035","rule":"章内のSpO₂区分表は回答用から外し、統一する医学的な基準・対象・条件を監修者に確認する。"}]', '5.0') ON CONFLICT (knowledge_id) DO NOTHING;